#include "endpoint.hpp"
#include <iostream>
using Bytes=std::vector<uint8_t>;
static cu66_port::Arena* owner=nullptr;
void cu66_allocation_observer(size_t){}
void* cu66_test_malloc(size_t n){return n>15616?nullptr:std::malloc(n);}
size_t free_probe(){return owner?116272-owner->live:116272;}
size_t largest_probe(){return 15616;}
void u16(Bytes&b,unsigned v){b.push_back(uint8_t(v));b.push_back(uint8_t(v>>8));}
void u32(Bytes&b,unsigned v){for(unsigned i=0;i<4;i++)b.push_back(uint8_t(v>>(8*i)));}
void seal(Bytes&b){u32(b,cu66::crc32({b.data(),b.size()}));}
Bytes full(const char*magic,unsigned mode,const Bytes&data,unsigned pixels=7680){Bytes b(magic,magic+4);b.push_back(1);b.push_back(uint8_t(mode));for(auto v:{168u,360u,320u,24u})u16(b,v);const bool palette=mode!=0;u16(b,palette?2:0);u32(b,pixels);u32(b,data.size());if(palette){u16(b,0);u16(b,65535);}b.insert(b.end(),data.begin(),data.end());seal(b);return b;}
void test_full(const char*label,Bytes b,int grammar,bool expected_good,size_t expectedmax){cu66_port::Arena a(98304);owner=&a;a.free_probe=free_probe;a.reserve=8192;a.largest_probe=largest_probe;bool good=false;{cu66_port::Scope scope(a);try{auto words=cu66::decode_full_patch({b.data(),b.size()},{168,360,320,24});cu66::need(words.size()==7680&&words.capacity()==7680,"exactcapacity");for(unsigned i=0;i<words.size();i++){unsigned want=grammar==0?i&65535:grammar==1?(i&1?65535:0):((i%320)>=128&&(i%320)<256?65535:0);cu66::need(words[i]==want,"wordoracle");}good=true;}catch(const std::exception&){if(expected_good)throw;}}cu66::need(good==expected_good&&a.live==0&&a.maximum==expectedmax,"fullmode result/max/live");std::cout<<label<<" good="<<good<<" maximum="<<a.maximum<<" failures="<<a.failures<<"\n";owner=nullptr;}
Bytes hd25(const Bytes&data){cu66_port::Arena tagarena(98304);cu66::Tag tag;{cu66_port::Scope scope(tagarena);cu66_port::Vector<uint16_t> words(7680);for(unsigned i=0;i<words.size();i++)words[i]=uint16_t(i);tag=cu66::patch_tag(words,320,24);}Bytes b={'H','D','2','5',1,0};u16(b,320);u16(b,24);u32(b,data.size());b.insert(b.end(),16,0);b.insert(b.end(),tag.begin(),tag.end());b.insert(b.end(),data.begin(),data.end());seal(b);return b;}
void test_hd(Bytes b,bool expected_good){cu66_port::Arena a(98304);owner=&a;a.free_probe=free_probe;a.reserve=8192;a.largest_probe=largest_probe;bool good=false;{cu66_port::Scope scope(a);try{auto words=cu66::decode_patch({b.data(),b.size()},nullptr,320,24);cu66::need(words.size()==7680&&words.capacity()==7680,"HDexactcapacity");for(unsigned i=0;i<words.size();i++)cu66::need(words[i]==i,"HDwordoracle");good=true;}catch(const std::exception&){if(expected_good)throw;}}cu66::need(good==expected_good&&a.live==0&&a.maximum==(expected_good?15360:0),"HDresult/max/live");std::cout<<"HD25raw good="<<good<<" maximum="<<a.maximum<<"\n";owner=nullptr;}
int main(){try{Bytes raw;for(unsigned i=0;i<7680;i++)u16(raw,i);Bytes pal(960,0x55),rle;for(unsigned y=0;y<24;y++){u16(rle,6);for(auto v:{255,0,255,1,191,0})rle.push_back(v);}test_full("fullraw",full("HR01",0,raw),0,true,15360);test_full("HP01",full("HP01",1,pal),1,true,15360);test_full("HR01",full("HR01",2,rle),2,true,15360);test_hd(hd25(raw),true);raw.pop_back();raw.pop_back();test_full("badraw",full("HR01",0,raw),0,false,0);pal.pop_back();test_full("badHPbits",full("HP01",1,pal),1,false,4);test_hd(hd25(raw),false);std::cout<<"FOUR_BRANCH_EXACT15360_AND3NEGATIVE_PASS\n";return 0;}catch(const std::exception&e){std::cerr<<e.what()<<"\n";return 1;}}
